<script setup lang="ts">import { computed } from 'vue';import qrcode from 'qrcode-generator';const p=defineProps<{ value:string }>();const matrix=computed(()=>{if(!p.value)return {size:0,cells:[] as boolean[]};const qr=qrcode(0,'M');qr.addData(p.value);qr.make();const size=qr.getModuleCount();const cells:boolean[]=[];for(let y=0;y<size;y++)for(let x=0;x<size;x++)cells.push(qr.isDark(y,x));return {size,cells}})</script>
<template><view class="qr" :style="{padding:'12px'}"><view v-for="(_,index) in matrix.cells" :key="index" :class="['cell',{dark:matrix.cells[index]}]" :style="{width:`${100/matrix.size}%`,paddingTop:`${100/matrix.size}%`}"/></view></template><style scoped>.qr{display:flex;width:15rem;max-width:75vw;flex-wrap:wrap;background:#fff}.cell{height:0;background:#fff}.cell.dark{background:#18201d}</style>
